 foreach(var (icon,title,action) in new(string,string,Action)[]{("⌂","Home",Home),("♙","Account",Login),("↻","Refresh",()=>_ = Connect()),("×","Cancel loading",()=>operation?.Cancel()),("★","Favorites",()=>_ = ShowFavorites()),("↓","Downloads & recordings",ShowTransfers),("▣","Multiscreen",()=>_ = Multiscreen()),("≡","EPG",()=>_ = Guide(false)),("⚙","Settings",Settings),("ⓘ","About",About),("⇥","Exit",Close)})tools.Controls.Add(new CircleTool(icon,title,action));
