 var labels=new[]{"LIVE TV","MOVIES","SERIES","MULTISCREEN","EPG","CATCH-UP"};var glyphs=new[]{"▣","▶","▰","▤","≡","◷"};var colors=new[]{(Color.FromArgb(22,51,255),Color.FromArgb(7,17,170)),(Color.FromArgb(255,31,33),Color.FromArgb(183,0,2)),(Color.FromArgb(32,200,15),Color.FromArgb(3,112,4)),(Color.FromArgb(156,26,239),Color.FromArgb(68,0,193)),(Color.FromArgb(42,139,255),Color.FromArgb(15,67,161)),(Color.FromArgb(255,173,28),Color.FromArgb(241,112,0))};for(int i=0;i<6;i++){int n=i;var tile=new Tile{Text=labels[i],Glyph=glyphs[i],First=colors[i].Item1,Last=colors[i].Item2,Dock=DockStyle.Fill,Margin=new(9)};tile.Click+=async(_,_)=>{if(n<3)await OpenCatalog(new[]{"Live TV","Movies","Series"}[n]);else if(n==3)await Multiscreen();else await Guide(n==5);};tiles.Controls.Add(tile);}
 var right=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,Padding=new(8)};right.RowStyles.Add(new(SizeType.Percent,100));right.RowStyles.Add(new(SizeType.Absolute,86));monitor=new MonitorCard{Dock=DockStyle.Fill,Margin=new(3,9,3,9)};right.Controls.Add(monitor);var resume=new Tile{Dock=DockStyle.Fill,Text="Continue Watching",Glyph="▶",First=Color.FromArgb(42,40,255),Last=Color.FromArgb(140,33,222)};resume.Click+=(_,_)=>Continue();right.Controls.Add(resume);layout.Controls.Add(right,1,0);
 var counts=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=6,RowCount=1,Padding=new(6),BackColor=Color.Transparent};counts.RowStyles.Add(new(SizeType.Percent,100));for(int i=0;i<6;i++)counts.ColumnStyles.Add(new(SizeType.Percent,16.666f));string count(string k)=>catalogs.TryGetValue(k,out var items)?items.Count.ToString("N0"):"Not loaded";string expiry=saved.Mode=="Xtream Codes"?provider.Info.Expiry:"Provider managed";string[] values={"Expiry Date\n"+expiry,"LIVE TV\n"+count("Live TV"),"MOVIES\n"+count("Movies"),"SERIES\n"+count("Series"),"TOTAL LOADED\n"+catalogs.Values.Sum(c=>c.Count).ToString("N0"),"Logged In\n"+(saved.User.Length>0?saved.User:catalogs.Count>0?"M3U":"Not connected")};foreach(string value in values){var box=new RoundedPanel{Dock=DockStyle.Fill,Margin=new(5),Padding=new(12)};var label=new Label{Text=value,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,ForeColor=Ui.Text,Font=new("Segoe UI",11,FontStyle.Bold),BackColor=Color.Transparent};box.Controls.Add(label);counts.Controls.Add(box);}layout.Controls.Add(counts,0,1);layout.SetColumnSpan(counts,2);SetBody(layout);SetStatus("Independent Windows player • Connect your own IPTV subscription");}
 async Task Connect(bool fallback=false){if(demo){SetStatus("Demo uses synthetic channels; connect from Account for real content.");return;}if(string.IsNullOrWhiteSpace(saved.Server)){Login();return;}await Run(async token=>{SetStatus("Connecting to provider…");provider.Dispose();provider=new(saved);catalogs.Clear();playlistEpisodes.Clear();if(saved.Mode=="M3U"||fallback){var raw=await provider.M3u(fallback,token);foreach(var group in raw.Where(c=>c.Kind!="Episode").GroupBy(c=>c.Kind))catalogs[group.Key]=group.ToList();foreach(var series in raw.Where(c=>c.Kind=="Episode").GroupBy(c=>c.SeriesTitle)){var first=series.First();string key="m3u-series:"+Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(series.Key)))[..16];playlistEpisodes[key]=series.ToList();if(!catalogs.ContainsKey("Series"))catalogs["Series"]=new();catalogs["Series"].Add(first with {Name=series.Key,Url=key,Kind="Series"});}}else{await provider.Authenticate(token);SetStatus("Loading Live TV and provider categories…");catalogs["Live TV"]=await provider.Catalog("Live TV",token);}TrySave();await ShowLibrary("Live TV");SetStatus("Connected. Movies and Series load when opened.");});}
 async Task<bool> Ensure(string kind){if(catalogs.ContainsKey(kind))return true;if(demo){catalogs[kind]=new();return true;}if(saved.Server.Length==0){Login();return false;}if(saved.Mode=="M3U"){if(catalogs.Count==0)await Connect();return catalogs.ContainsKey(kind);}bool loaded=false;await Run(async token=>{if(provider.Info.Status=="Not connected")await provider.Authenticate(token);SetStatus("Loading "+kind+"…");catalogs[kind]=await provider.Catalog(kind,token);loaded=true;});return loaded;}
 async Task OpenCatalog(string kind){if(await Ensure(kind))await ShowLibrary(kind);else if(saved.Mode=="M3U"&&catalogs.Count>0)SetStatus("This M3U contains no categorized "+kind+" entries.");}
 async Task ShowLibrary(string kind){currentKind=kind;var source=kind=="Favorites"?catalogs.Values.SelectMany(x=>x).Concat(saved.FavoriteItems).Where(c=>saved.Favorites.Contains(c.Url)).DistinctBy(c=>c.Url).ToArray():catalogs.GetValueOrDefault(kind,new()).ToArray();var custom=new Dictionary<string,ChannelOverride>(saved.Organization);SetStatus("Organizing "+kind+"…");var entries=await Task.Run(()=>source.Select(c=>new BrowserEntry(c,CatalogDirectory.Locate(c,custom))).ToArray());if(closing)return;var browser=new LibraryBrowser(kind,entries,saved,player,Play,Favorite,Download,c=>_ = Record(c),c=>_ = OpenGuide(c,false),()=>{TrySave();_ = ShowLibrary(currentKind);},!demo);SetBody(browser); // SetBody detaches the persistent player; attach it to the browser's video host again.
 browser.AttachPlayer(player);SetStatus(kind+" • "+entries.Length.ToString("N0")+" titles • country → genre → title");}
