 void SaveHistory(){if(player.Media is not{} media)return;var s=player.Engine.State;if(s.State is not (3 or 4))return;saved.History.RemoveAll(h=>h.Media.Url==media.Url);long position=media.Kind=="Live TV"||s.Length>0&&s.Time>s.Length-10000?0:s.Time;saved.History.Insert(0,new(media,position,DateTimeOffset.Now));if(saved.History.Count>40)saved.History.RemoveRange(40,saved.History.Count-40);}
 void Continue(){if(saved.History.FirstOrDefault() is{} recent)Play(recent.Media);else SetStatus("Nothing watched yet. Play a movie, episode or live channel first.");}
 void Favorite(Channel media){if(saved.Favorites.Remove(media.Url))saved.FavoriteItems.RemoveAll(c=>c.Url==media.Url);else{saved.Favorites.Add(media.Url);saved.FavoriteItems.RemoveAll(c=>c.Url==media.Url);saved.FavoriteItems.Add(media);}TrySave();SetStatus(saved.Favorites.Contains(media.Url)?"Added to Favorites":"Removed from Favorites");}
 void Download(Channel media){try{var job=transfers.Download(media,Path.Combine(saved.DownloadFolder,"Downloads"));SetStatus("Download queued: "+job.Name);ShowTransfers();}catch(Exception e){Error(e);}}
 async Task Record(Channel media){if(media.Kind!="Live TV"){SetStatus("Recording is for live channels; use Download for a movie or episode.");return;}using var dialog=new Form{Text="Record live programme",Size=new(490,260)};Ui.Dark(dialog);var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new(18)};dialog.Controls.Add(p);p.Controls.Add(new Label{Text=media.Name,AutoSize=true});var stopPreview=new CheckBox{Text="Stop preview to free a provider connection",Checked=true,AutoSize=true};p.Controls.Add(stopPreview);var minutes=new NumericUpDown{Minimum=0,Maximum=1440,Value=60,Width=100};p.Controls.Add(new Label{Text="Duration in minutes (0 = until stopped)",AutoSize=true});p.Controls.Add(minutes);bool go=false;p.Controls.Add(Ui.Button("Start recording",()=>{go=true;dialog.Close();}));dialog.ShowDialog(this);if(!go)return;try{if(stopPreview.Checked)await player.Engine.StopAsync().WaitAsync(TimeSpan.FromSeconds(12));var job=transfers.Capture(media,Path.Combine(saved.DownloadFolder,"Recordings"),true);if(minutes.Value>0)job.Cancellation.CancelAfter(TimeSpan.FromMinutes((double)minutes.Value));ShowTransfers();}catch(Exception e){Error(e);}}
