 async Task Guide(bool catchup){if(await Ensure("Live TV")){var channels=catalogs.GetValueOrDefault("Live TV",new());if(catchup)channels=channels.Where(c=>c.HasArchive).ToList();if(channels.Count==0){SetStatus(catchup?"Your provider has not advertised any archive-enabled channels.":"No live channels available.");return;}await OpenGuide(channels[0],catchup,channels);}}
