 bool exitApproved,exitInProgress;
 async void CloseRequested(object? sender,FormClosingEventArgs e){if(exitApproved)return;e.Cancel=true;if(exitInProgress)return;if(transfers.Jobs.Any(j=>j.Active)&&MessageBox.Show(this,"Downloads or recordings are active. Stop and finalize them before exiting?","Exit",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;exitInProgress=true;SetStatus("Closing playback and finalizing active recordings…");foreach(var job in transfers.Jobs.Where(j=>j.Active))job.Stop();try{await Task.WhenAll(transfers.Jobs.Where(j=>j.Work!=null).Select(j=>j.Work!)).WaitAsync(TimeSpan.FromSeconds(20));}catch{SetStatus("Some transfers could not finalize; partial files are retained.");}foreach(var multi in OwnedForms.OfType<MultiscreenWindow>().ToArray())await multi.Shutdown();try{await player.Engine.StopAsync().WaitAsync(TimeSpan.FromSeconds(8));player.Engine.Dispose();await player.Engine.Completion.WaitAsync(TimeSpan.FromSeconds(3));}catch{}exitApproved=true;Close();}
